{
  "items": [
    {
      "name": "MvPolynomial.combinatorial_nullstellensatz_exists_linearCombination",
      "module_name": "Mathlib.Combinatorics.Nullstellensatz",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {σ : Type u_2} [Finite σ] [IsDomain R] (S : σ → Finset R),\n  (∀ (i : σ), (S i).Nonempty) →\n    ∀ (f : MvPolynomial σ R),\n      (∀ (x : σ → R), (∀ (i : σ), x i ∈ S i) → (MvPolynomial.eval x) f = 0) →\n        ∃ h,\n          (∀ (i : σ), ((∏ s ∈ S i, (MvPolynomial.X i - MvPolynomial.C s)) * h i).totalDegree ≤ f.totalDegree) ∧\n            f =\n              (Finsupp.linearCombination (MvPolynomial σ R) fun i => ∏ r ∈ S i, (MvPolynomial.X i - MvPolynomial.C r)) h"
    },
    {
      "name": "IsAlgebraic.exists_nonzero_coeff_and_aeval_eq_zero",
      "module_name": "Mathlib.RingTheory.Algebraic.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [inst_1 : Ring S] [inst_2 : Algebra R S] {s : S},\n  IsAlgebraic R s → s ∈ nonZeroDivisors S → ∃ q, q.coeff 0 ≠ 0 ∧ (Polynomial.aeval s) q = 0"
    },
    {
      "name": "LindemannWeierstrass.exp_polynomial_approx",
      "module_name": "Mathlib.NumberTheory.Transcendental.Lindemann.AnalyticalPart",
      "kind": "theorem",
      "type": "∀ (f : Polynomial ℤ),\n  Polynomial.eval 0 f ≠ 0 →\n    ∃ c,\n      ∀ p > (Polynomial.eval 0 f).natAbs,\n        Nat.Prime p →\n          ∃ n,\n            ¬↑p ∣ n ∧\n              ∃ gp,\n                gp.natDegree ≤ p * f.natDegree - 1 ∧\n                  ∀ {r : ℂ},\n                    r ∈ f.aroots ℂ → ‖n • Complex.exp r - p • (Polynomial.aeval r) gp‖ ≤ c ^ p / ↑(p - 1).factorial"
    },
    {
      "name": "Polynomial.exists_monic_aeval_eq_zero_forall_mem_pow_of_isIntegral",
      "module_name": "Mathlib.RingTheory.IntegralClosure.Algebra.Ideal",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S] {I : Ideal R} {x : S},\n  IsIntegral (↥(Algebra.adjoin R {x | ∃ r ∈ I, Polynomial.C r * Polynomial.X = x})) (Polynomial.C x * Polynomial.X) →\n    ∃ p, p.Monic ∧ (Polynomial.aeval x) p = 0 ∧ ∀ (i : ℕ), p.coeff i ∈ I ^ (p.natDegree - i)"
    },
    {
      "name": "Poly.isPoly",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f : Poly α), IsPoly ⇑f"
    },
    {
      "name": "LaurentSeries.exists_Polynomial_intValuation_lt",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {K : Type u_2} [inst : Field K] (F : PowerSeries K) (η : (WithZero (Multiplicative ℤ))ˣ),\n  ∃ P, (PowerSeries.idealX K).intValuation (F - ↑P) < ↑η"
    },
    {
      "name": "Poly.instInhabited",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "instance",
      "type": "(α : Type u_3) → Inhabited (Poly α)"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Fin n → Finset R),\n      ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤\n        p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card"
    }
  ]
}
